import{_ as s,C as n,c as r,o as i,a3 as t,G as o}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Stages","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/configuration/stages.md","filePath":"master/sales/crm/configuration/stages.md","lastUpdated":1793789158000}'),l={name:"master/sales/crm/configuration/stages.md"};function h(g,e,d,c,p,m){const a=n("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="stages" tabindex="-1">Stages <a class="header-anchor" href="#stages" aria-label="Permalink to &quot;Stages&quot;">​</a></h1><p>Stages are the steps an opportunity moves through, from first contact to a won deal. They are the columns of your pipeline board. Every opportunity sits in exactly one stage, so the board shows where each deal stands.</p><blockquote><p><strong>In simple words:</strong> A stage is one step on the road from a new deal to a won deal. You decide the steps and their order.</p></blockquote><p>Open <code>CRM → Configuration → Pipeline → Stages</code>.</p><h2 id="the-stage-list" tabindex="-1">The stage list <a class="header-anchor" href="#the-stage-list" aria-label="Permalink to &quot;The stage list&quot;">​</a></h2>',5)),o(a,{src:"/images1/crm/stages-list.png",alt:"Stages list showing New, Qualified, Proposition and Won with the Sales Teams, Won Stage and Opportunities columns"}),e[1]||(e[1]=t('<p>The list opens on one screen with no tabs. The default stages are <strong>New</strong>, <strong>Qualified</strong>, <strong>Proposition</strong> and <strong>Won</strong>.</p><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><ul><li><strong><em>Stage Name:</em></strong> The name of the stage.</li><li><strong><em>Sales Teams:</em></strong> The teams that use the stage, as badges. It shows <strong>All teams</strong> when no team is chosen.</li><li><strong><em>Won Stage:</em></strong> A tick when the stage counts as won.</li><li><strong><em>Requirements:</em></strong> The guidance text, cut short after 60 characters. You can hide this column.</li><li><strong><em>Opportunities:</em></strong> How many leads and opportunities sit in the stage.</li><li><strong><em>Created At:</em></strong> Hidden at first. Show it with the column toggle.</li></ul><p><strong>Example:</strong> In the dev data, <strong>New</strong> holds 20 records, <strong>Qualified</strong> 4, <strong>Proposition</strong> 5 and <strong>Won</strong> 3. <strong>Won</strong> has the tick in <strong>Won Stage</strong>.</p><h3 id="search-order-and-export" tabindex="-1">Search, order and export <a class="header-anchor" href="#search-order-and-export" aria-label="Permalink to &quot;Search, order and export&quot;">​</a></h3><ul><li>Type in the search box to find a stage by name.</li><li>Drag the handle of a row to change the order. The board shows the stages in the same order.</li><li>Select rows and use the bulk action to export them.</li></ul><h2 id="create-a-stage" tabindex="-1">Create a stage <a class="header-anchor" href="#create-a-stage" aria-label="Permalink to &quot;Create a stage&quot;">​</a></h2><ol><li>Go to <code>CRM → Configuration → Pipeline → Stages</code>.</li><li>Click <strong>New Stage</strong>.</li><li>Fill in the form.</li><li>Click <strong>Create</strong>.</li></ol>',8)),o(a,{src:"/images1/crm/stages-form.png",alt:"Create Stage dialog filled with the name Negotiation and a requirement note, with Sales Teams left empty"}),e[2]||(e[2]=t('<ul><li><strong><em>Stage Name:</em></strong> The name on the board column. Required. Up to 255 characters.</li><li><strong><em>Sales Teams:</em></strong> The teams whose pipeline shows this stage. You can pick several. Leave it empty to share the stage with all teams.</li><li><strong><em>Is Won Stage?:</em></strong> Switch on if an opportunity that reaches this stage counts as won. It is off at first. Moving a deal here sets its probability to 100%.</li><li><strong><em>Requirements:</em></strong> Internal guidance on what must be done before a deal moves to this stage. Text, three rows high.</li></ul><p><strong>Example:</strong> Name <code>Negotiation</code>, leave <strong>Sales Teams</strong> empty, leave <strong>Is Won Stage?</strong> off, and write <code>Quote sent and price discussed</code> in <strong>Requirements</strong>.</p><p>A notice says the stage was created.</p><h2 id="edit-a-stage" tabindex="-1">Edit a stage <a class="header-anchor" href="#edit-a-stage" aria-label="Permalink to &quot;Edit a stage&quot;">​</a></h2><ol><li>Click <strong>Edit</strong> at the end of the row.</li><li>Change the fields.</li><li>Click <strong>Save</strong>. A notice says <strong>Stage updated</strong>.</li></ol><h2 id="delete-a-stage" tabindex="-1">Delete a stage <a class="header-anchor" href="#delete-a-stage" aria-label="Permalink to &quot;Delete a stage&quot;">​</a></h2><ol><li>Click <strong>Delete</strong> at the end of the row.</li><li>Confirm.</li></ol><p>A stage can only be deleted when no record uses it. Aureus counts every lead and opportunity in the stage, lost ones too. If any exist, the dialog lists the count and has no confirm button. A red notice says the stage can&#39;t be deleted and asks you to move its records to another stage first.</p><h2 id="stages-on-the-pipeline-board" tabindex="-1">Stages on the pipeline board <a class="header-anchor" href="#stages-on-the-pipeline-board" aria-label="Permalink to &quot;Stages on the pipeline board&quot;">​</a></h2><p>The board is built from the stages you see here. A stage with chosen <strong>Sales Teams</strong> shows only on the board of those teams. A stage with no team shows for everyone.</p><p>You can also add, edit or delete a column from the board. See <a href="./../pipeline/manage-opportunities.html">Manage opportunities</a>.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li>Opportunities in a stage with <strong>Is Won Stage?</strong> on count as won. The <strong>Won</strong> tabs and reports use that rule.</li><li>The <strong>Won</strong> button on an opportunity moves it to a won stage. You need at least one such stage, or the button cannot finish. See <a href="./../pipeline/mark-won-lost.html">Mark won or lost</a>.</li><li>Reports group by stage in the order you set here.</li><li>Changing the name or order does not touch the opportunities. They stay in the same stage.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Keep the list short. Four to six stages are easy to read on a board.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Move the records out of a stage before you delete it. Aureus will not delete a stage that still has records.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../pipeline/manage-opportunities.html">Manage opportunities</a></li><li><a href="./../pipeline/mark-won-lost.html">Mark won or lost</a></li><li><a href="./../reporting/pipeline-analysis.html">Pipeline analysis</a></li><li><a href="./">CRM configuration</a></li></ul>',17))])}const b=s(l,[["render",h]]);export{f as __pageData,b as default};
